import"./app.min.js";import"./slider.min.js";import"./products.min.js";import"./products.min2.js";const S=document.querySelectorAll("[data-coundown]");if(S.length){const n=()=>{S.forEach(e=>{const a=e.dataset.coundown;if(!a)return;let t=Date.parse(a)-Date.now();t<0&&(t=0);const r=1e3*60*60*24,s=1e3*60*60,c=1e3*60,i=1e3,l=Math.floor(t/r),d=Math.floor(t%r/s),u=Math.floor(t%s/c),p=Math.floor(t%c/i),o=e.querySelectorAll(".countdown__digits span");o.length&&(o[0].textContent=String(l).padStart(2,"0"),o[1].textContent=String(d).padStart(2,"0"),o[2].textContent=String(u).padStart(2,"0"),o[3].textContent=String(p).padStart(2,"0"))})};n(),setInterval(n,1e3)}
